#!/usr/bin/env python3
"""Compose Telegram campaign layouts from approved artwork, with editable copy."""
from pathlib import Path
from telegram_design import PHONE_CSS,phone,PLANE
ROOT=Path(__file__).resolve().parents[1]
DEST=ROOT/'assets/telegram';DEST.mkdir(exist_ok=True)
CSS='''*{box-sizing:border-box}html,body{margin:0;padding:0;background:#FFFCF8;color:#0C0C0C;font-family:Satoshi,Arial,sans-serif}body{width:1080px}.canvas{width:1080px;height:1350px;padding:58px 64px;overflow:hidden;position:relative}.brand{font:19px "IBM Plex Mono",monospace;display:flex;justify-content:space-between;text-transform:none;border-bottom:2px solid;padding-bottom:20px}.heading{font-family:Archivo,Arial,sans-serif;font-weight:900;font-size:66px;line-height:1.04;letter-spacing:-3px;margin:30px 0 24px}.red{color:#c6121f}.sub{font-size:26px;line-height:1.35;margin:0 0 24px}.row{display:grid;grid-template-columns:230px 1fr;align-items:center;gap:30px;border-top:2px solid #141414;padding:20px 0;min-height:236px}.visual{height:200px;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center}.visual img{width:100%;height:100%;object-fit:contain}.device{position:relative;height:200px;width:112px}.device .telegram-phone{position:absolute;left:0;top:0;transform:scale(.565);transform-origin:top left}.comic-art{position:relative;height:200px;width:200px;overflow:hidden}.comic-art img{position:absolute;left:0;top:0;width:300%;height:200%;max-width:none;object-fit:fill}.eyebrow{font:16px "IBM Plex Mono",monospace;color:#c6121f;display:block;margin-bottom:9px}.row h2{font:900 42px Archivo,Arial,sans-serif;letter-spacing:-1.7px;margin:0 0 12px}.row p{font-size:25px;line-height:1.3;margin:0;max-width:25ch}.footer{border-top:3px solid #141414;margin-top:8px;padding-top:22px;font-size:23px;line-height:1.4}.footer strong{display:block;font:900 29px Archivo,Arial,sans-serif}.footer small{font-size:18px}.square{height:1080px;text-align:center;padding:0}.avatar-art{position:absolute;left:150px;top:80px;width:780px;height:780px;object-fit:contain}.avatar-title{position:absolute;top:790px;left:90px;right:90px;font:900 94px Archivo,Arial,sans-serif;letter-spacing:-5px}.avatar-tag{position:absolute;top:915px;left:0;right:0;font:25px "IBM Plex Mono",monospace}.avatar-badge{position:absolute;right:168px;top:625px;width:120px;height:120px;border:8px solid #FFFCF8;border-radius:50%;background:#279bd3;color:white;display:flex;align-items:center;justify-content:center}.avatar-badge svg{width:67px;height:67px}
'''
def html(title,body):
 return '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><link href="https://api.fontshare.com/v2/css?f[]=satoshi@400,500,700,900&display=swap" rel="stylesheet"><link href="https://fonts.googleapis.com/css2?family=Archivo:wght@600;800;900&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet"><style>'+CSS+PHONE_CSS+'</style></head><body>'+body+'</body></html>'
announcement='''<main class="canvas"><div class="brand"><span>Le Radar iA</span><span>Hugo Lahutte × iAstro</span></div><h1 class="heading">Ta veille IA.<br><span class="red">Maintenant en audio<br>et en comic.</span></h1><p class="sub">Trois façons de garder le fil.</p><div class="row"><div class="visual"><span class="device">'''+phone()+'''</span></div><div><span class="eyebrow">01 / CHAQUE JOUR SUR TELEGRAM</span><h2>Le Radar iA</h2><p>Les annonces à retenir,<br>avec leurs sources.</p></div></div><div class="row"><div class="visual"><img src="/assets/podcast/art/iastro-10-v1.png" alt="iAstro avec son casque"></div><div><span class="eyebrow">02 / À ÉCOUTER</span><h2>Le Podcast iA</h2><p>Le Flash pour l’essentiel.<br>Le Débrief pour approfondir.</p></div></div><div class="row"><div class="visual"><span class="comic-art"><img src="/knowledge-hub/comics/art/2026-W41/mistral-v1.png" alt="Hugo et iAstro dans le comic"></span></div><div><span class="eyebrow">03 / UN COMIC CHAQUE SEMAINE</span><h2>iAstro Sunday</h2><p>Les grandes nouvelles de l’IA,<br>racontées en images.</p></div></div><footer class="footer"><strong>À retrouver dans Le Kiosque IA ↗</strong>hl-consulting.tech/knowledge-hub/immersion-ia/<br><small>Telegram : @VeilleIA_HL · Premier comic déjà disponible</small></footer></main>'''
avatar='''<main class="canvas square"><img class="avatar-art" src="/assets/podcast/art/iastro-10-v1.png" alt="iAstro, version octobre"><span class="avatar-badge">'''+PLANE+'''</span><div class="avatar-title">Le Radar <span class="red">iA</span></div><div class="avatar-tag">LIRE · ÉCOUTER · EXPLORER</div></main>'''
for name,title,body in [('annonce-trois-formats','Annonce Telegram — trois formats',announcement),('avatar-radar-octobre','Avatar Le Radar iA — octobre',avatar)]:
 (DEST/(name+'.html')).write_text(html(title,body))
print('Deux compositions Telegram préparées.')
if __name__=='__main__':pass
